import { test, expect } from '@playwright/test';

test.describe('Popover Toggle on Button Click', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/popover-toggle');
  });

  test('should toggle popover visibility on button click', async ({ page }) => {
    // Verify popover is not visible initially
    const popover = page.getByRole('dialog');
    await expect(popover).not.toBeVisible();

    // Verify button is visible and enabled
    const toggleButton = page.getByRole('button', { name: /toggle popover/i });
    await expect(toggleButton).toBeVisible();

    // Click the toggle button to open the popover
    await toggleButton.click();

    // Verify popover is now visible
    await expect(popover).toBeVisible();

    // Verify popover content is displayed
    const popoverContent = page.getByText(/popover content/i);
    await expect(popoverContent).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click the close button to close the popover
    await closeButton.click();

    // Verify popover is hidden again
    await expect(popover).not.toBeVisible();
  });

  test('should handle multiple clicks and maintain state', async ({ page }) => {
    // Verify popover is not visible initially
    const popover = page.getByRole('dialog');
    await expect(popover).not.toBeVisible();

    // Verify button is visible and enabled
    const toggleButton = page.getByRole('button', { name: /toggle popover/i });
    await expect(toggleButton).toBeVisible();

    // Click the toggle button to open the popover
    await toggleButton.click();
    await expect(popover).toBeVisible();

    // Click the toggle button again to close the popover
    await toggleButton.click();
    await expect(popover).not.toBeVisible();

    // Click the toggle button a third time to open the popover
    await toggleButton.click();
    await expect(popover).toBeVisible();

    // Verify popover content is still displayed
    const popoverContent = page.getByText(/popover content/i);
    await expect(popoverContent).toBeVisible();

    // Verify close button is still visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click the close button to close the popover
    await closeButton.click();

    // Verify popover is hidden again
    await expect(popover).not.toBeVisible();
  });
});
